SELECT t1.comment_id, t1.xhs_normal_count, t1.xhs_intercept_count, t2.comment_complete_id, t1.comment_content, t2.remark, t2.check_status, t2.xhs_note_info, t2.create_time, t3.account_name FROM biz_prompt_comment t1 JOIN biz_prompt_comment_complete t2 ON t1.comment_id = t2.comment_id LEFT JOIN biz_media_account t3 ON t2.media_account_id = t3.account_id WHERE t2.check_status = 0 AND t1.del_flag = '0' AND t2.del_flag = '0'
AND t1.comment_id = #{bo.commentId}
AND t2.media_account_id = #{bo.mediaAccountId}
ORDER BY t2.comment_complete_id DESC
